import { sql } from 'drizzle-orm';
import {
  boolean,
  check,
  foreignKey,
  index,
  integer,
  numeric,
  pgTable,
  smallint,
  text,
  timestamp,
  unique,
  uuid,
} from 'drizzle-orm/pg-core';
import { exercises } from './exercises';
import { gyms } from './gyms';
import { planExercises } from './plan-exercises';
import { workoutSessions } from './workout-sessions';

/**
 * Gym-owned (RLS on `gym_id`). One logged set. The id is generated by the client (idempotent
 * retries). `measure` is copied from the exercise when the set is created and decides which of
 * reps / weight / duration are filled. A not-yet-done pre-filled row still carries values (the
 * client sends 0 reps / 0 kg, or the target duration), so the CHECKs stay strict.
 * `plan_exercise_id` is `ON DELETE SET NULL (plan_exercise_id)` in the migration (see sessions).
 */
export const workoutSets = pgTable(
  'workout_sets',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    gymId: uuid('gym_id')
      .notNull()
      .references(() => gyms.id),
    sessionId: uuid('session_id').notNull(),
    exerciseId: uuid('exercise_id').notNull(),
    planExerciseId: uuid('plan_exercise_id'),
    measure: text('measure').notNull(),
    setIndex: smallint('set_index').notNull(),
    reps: smallint('reps'),
    weightKg: numeric('weight_kg', { precision: 5, scale: 2 }),
    durationSeconds: integer('duration_seconds'),
    done: boolean('done').notNull(),
    loggedAt: timestamp('logged_at', { withTimezone: true }).notNull(),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    foreignKey({
      name: 'workout_sets_session_gym_fk',
      columns: [t.sessionId, t.gymId],
      foreignColumns: [workoutSessions.id, workoutSessions.gymId],
    }).onDelete('cascade'),
    foreignKey({
      name: 'workout_sets_exercise_gym_fk',
      columns: [t.exerciseId, t.gymId],
      foreignColumns: [exercises.id, exercises.gymId],
    }),
    foreignKey({
      name: 'workout_sets_plan_exercise_gym_fk',
      columns: [t.planExerciseId, t.gymId],
      foreignColumns: [planExercises.id, planExercises.gymId],
    }).onDelete('set null'),
    unique('workout_sets_session_exercise_index_uq').on(t.sessionId, t.exerciseId, t.setIndex),
    check('workout_sets_measure_chk', sql`${t.measure} in ('weight_reps', 'reps', 'duration')`),
    check('workout_sets_index_chk', sql`${t.setIndex} between 0 and 99`),
    check('workout_sets_reps_chk', sql`${t.reps} is null or ${t.reps} between 0 and 100`),
    check(
      'workout_sets_weight_chk',
      sql`${t.weightKg} is null or (${t.weightKg} between 0 and 999.75 and ${t.weightKg} * 4 = trunc(${t.weightKg} * 4))`,
    ),
    check(
      'workout_sets_duration_chk',
      sql`${t.durationSeconds} is null or ${t.durationSeconds} between 1 and 7200`,
    ),
    check(
      'workout_sets_values_chk',
      sql`(${t.measure} = 'weight_reps' and ${t.reps} is not null and ${t.weightKg} is not null and ${t.durationSeconds} is null)
        or (${t.measure} = 'reps' and ${t.reps} is not null and ${t.weightKg} is null and ${t.durationSeconds} is null)
        or (${t.measure} = 'duration' and ${t.durationSeconds} is not null and ${t.reps} is null and ${t.weightKg} is null)`,
    ),
    // A set marked done must have actually been performed.
    check('workout_sets_done_chk', sql`not ${t.done} or coalesce(${t.reps}, 1) >= 1`),
    // Keeps the plan-exercise SET NULL (plan edits delete plan exercises) from scanning every set.
    index('workout_sets_plan_exercise_idx')
      .on(t.planExerciseId)
      .where(sql`${t.planExerciseId} is not null`),
  ],
);
